<template>
  <div class="page-head"><div><h2>项目与区域</h2><span class="muted">管理施工项目、真实区域边界及历史水害影响</span></div><n-button @click="load">刷新</n-button></div>
  <div class="area-layout">
    <n-card title="施工项目" class="project-panel">
      <n-button type="primary" block @click="newProject">新增项目</n-button>
      <div class="project-list"><button v-for="p in projects" :key="p.id" :class="{active:selectedProject?.id===p.id}" @click="selectProject(p)"><b>{{p.project_name}}</b><span>{{p.project_type_label}} · {{p.work_area_count}} 个区域</span><n-tag size="small" :type="p.status==='active'?'success':'default'">{{p.status==='active'?'进行中':'已归档'}}</n-tag></button></div>
    </n-card>
    <div class="area-main">
      <n-card v-if="showProjectForm" :title="projectForm.id?'编辑项目':'新增项目'" class="form-card">
        <div class="form-grid"><n-input v-model:value="projectForm.project_name" placeholder="项目名称"/><n-input v-model:value="projectForm.project_code" placeholder="项目编号"/><n-select v-model:value="projectForm.project_type" :options="projectTypes" placeholder="项目类型"/><n-input v-model:value="projectForm.location_text" placeholder="位置说明（可选）"/><n-input v-model:value="projectForm.description" type="textarea" placeholder="项目说明（可选）" class="wide"/></div>
        <n-space justify="end"><n-button @click="showProjectForm=false">取消</n-button><n-button type="primary" :loading="saving" @click="saveProject">保存项目</n-button></n-space>
      </n-card>
      <template v-if="selectedProject">
        <n-card class="project-summary"><div class="summary-head"><div><h3>{{selectedProject.project_name}}</h3><span>{{selectedProject.project_code}} · {{selectedProject.project_type_label}} · {{selectedProject.location_text||'未填写位置'}}</span></div><n-space><n-button @click="editProject">编辑</n-button><n-popconfirm v-if="selectedProject.status==='active'" @positive-click="archiveProject"><template #trigger><n-button type="warning" secondary>归档项目</n-button></template>归档后保留全部区域和历史影响，是否继续？</n-popconfirm><n-button type="primary" :disabled="selectedProject.status!=='active'" @click="newArea">新增施工区域</n-button></n-space></div></n-card>
        <n-card title="项目降雨背景"><n-descriptions v-if="rainOverview?.has_data" bordered :column="5" size="small"><n-descriptions-item label="雨量站">{{rainOverview.station_count}}</n-descriptions-item><n-descriptions-item label="观测记录">{{rainOverview.observation_count}}</n-descriptions-item><n-descriptions-item label="最近24小时">{{rain(rainOverview.rainfall_24h_mm)}}</n-descriptions-item><n-descriptions-item label="最近72小时">{{rain(rainOverview.rainfall_72h_mm)}}</n-descriptions-item><n-descriptions-item label="最近7天">{{rain(rainOverview.rainfall_7d_mm)}}</n-descriptions-item><n-descriptions-item label="最近观测">{{fmt(rainOverview.latest_observation_at||'')}}</n-descriptions-item><n-descriptions-item label="最近事件" :span="4">{{rainOverview.latest_event?`${fmt(rainOverview.latest_event.start_time)} 至 ${fmt(rainOverview.latest_event.end_time)}，累计 ${rainOverview.latest_event.total_rainfall_mm.toFixed(2)} mm`:'暂无已生成事件'}}</n-descriptions-item></n-descriptions><n-empty v-else description="暂无降雨观测数据"/><p class="muted">项目级观测不按施工区域进行空间插值；无数据不表示没有降雨。</p></n-card>
        <n-card title="无人机影像与多源时间轴"><n-descriptions v-if="uavSummary" bordered :column="4" size="small"><n-descriptions-item label="无人机影像">{{uavSummary.dataset_count}}</n-descriptions-item><n-descriptions-item label="最近航飞">{{uavSummary.latest_capture_time?fmt(uavSummary.latest_capture_time):'采集时间未填写'}}</n-descriptions-item><n-descriptions-item label="已覆盖施工区域">{{uavSummary.covered_work_area_count}}</n-descriptions-item><n-descriptions-item label="已完成人工复核">{{uavSummary.reviewed_count}}</n-descriptions-item></n-descriptions><n-timeline v-if="timeline.length" style="margin-top:16px"><n-timeline-item v-for="item in timeline" :key="item.type+item.source_id" :time="item.time?fmt(item.time):'时间未记录'" :title="item.label"/></n-timeline><n-empty v-else description="暂无已记录时间的多源事件"/><p class="muted">时间轴仅汇总数据库中的SAR、无人机、降雨、风险研判、设备位置与人工复核记录，不代表实时数字孪生。</p></n-card>
        <n-card v-if="showAreaForm" :title="areaForm.id?'编辑施工区域':'新增施工区域'" class="form-card">
          <div class="form-grid"><n-input v-model:value="areaForm.area_name" placeholder="区域名称"/><n-input v-model:value="areaForm.area_code" placeholder="区域编号"/><n-select v-model:value="areaForm.area_type" :options="areaTypes" placeholder="区域类型"/><n-input v-model:value="areaForm.crs" placeholder="空间参考，例如 EPSG:4326"/><n-input v-model:value="areaForm.description" placeholder="区域说明（可选）" class="wide"/><div class="wide upload-line"><input type="file" accept=".json,.geojson,application/geo+json" @change="readGeoJSON"><span>上传 Polygon / MultiPolygon GeoJSON，文件内容将规范化保存到数据库。</span></div><n-input v-model:value="areaForm.geometryText" type="textarea" :autosize="{minRows:6,maxRows:12}" placeholder='粘贴 GeoJSON Geometry 或 Feature，例如 {"type":"Polygon","coordinates":[...]}' class="wide code-input"/></div>
          <n-alert v-if="geoSummary" type="info" style="margin-bottom:12px">{{geoSummary}}</n-alert><n-space justify="end"><n-button @click="showAreaForm=false">取消</n-button><n-button type="primary" :loading="saving" @click="saveArea">保存施工区域</n-button></n-space>
        </n-card>
        <n-card title="施工区域"><n-data-table :columns="areaColumns" :data="areas" :loading="loading" :pagination="{pageSize:10}" :scroll-x="1100"/><n-empty v-if="!loading&&!areas.length" description="当前项目尚未配置施工区域边界"/></n-card>
      </template>
      <n-card v-else class="onboarding-panel">
        <div class="onboarding-content"><div class="onboarding-mark"><img src="/icons/factory.svg" alt=""></div><h3>从施工项目开始建立空间档案</h3><p>项目用于统一归集施工区域、工程机械、降雨背景及后续水害分析成果。</p><div class="onboarding-steps"><div><b>1. 建立项目</b><span>填写项目名称、编号和工程类型</span></div><div><b>2. 配置区域</b><span>录入真实作业区域及 GeoJSON 边界</span></div><div><b>3. 关联数据</b><span>在环境数据中心接入项目数据</span></div></div><n-button type="primary" @click="newProject">新增施工项目</n-button></div>
      </n-card>
    </div>
  </div>

  <n-modal v-model:show="detailVisible" preset="card" style="width:min(900px,92vw)" title="施工区域详情">
    <template v-if="detail"><n-descriptions bordered :column="3"><n-descriptions-item label="区域名称">{{detail.area_name}}</n-descriptions-item><n-descriptions-item label="区域类型">{{detail.area_type_label}}</n-descriptions-item><n-descriptions-item label="空间参考">{{detail.crs}}</n-descriptions-item><n-descriptions-item label="Geometry">{{detail.geometry_type}}</n-descriptions-item><n-descriptions-item label="状态">{{detail.status==='active'?'启用':'已归档'}}</n-descriptions-item><n-descriptions-item label="更新时间">{{fmt(detail.updated_at)}}</n-descriptions-item></n-descriptions><h4>无人机精细影像</h4><div class="terrain-tools"><n-select v-model:value="uavAreaDatasetId" :options="uavOptions" placeholder="选择项目无人机影像"/><n-button type="primary" :disabled="!uavAreaDatasetId" :loading="uavRunning" @click="runUavCoverage">分析区域覆盖</n-button><n-button tag="a" :href="api.uavCoverageCsvUrl(detail.project_id)" download>导出CSV</n-button></div><n-data-table v-if="uavCoverages.length" :columns="uavCoverageColumns" :data="uavCoverages" :pagination="false"/><n-empty v-else description="暂无覆盖该施工区域的无人机正射影像。"/><div class="area-uav-images"><img v-for="item in uavCoverages.filter(x=>x.crop_url)" :key="item.id" :src="item.crop_url||''"></div><n-data-table v-if="areaVerifications.length" :columns="verificationColumns" :data="areaVerifications" :pagination="false"/><p class="muted">影像覆盖只表示空间范围和有效像素覆盖，不表示影像质量或现场安全已经确认。</p><h4>地形特征</h4><div class="terrain-tools"><n-select v-model:value="terrainDemId" :options="terrainOptions" placeholder="选择项目DEM"/><n-button type="primary" :disabled="!terrainDemId" :loading="terrainRunning" @click="runTerrain">分析区域地形</n-button><n-button v-if="terrainProfiles.length" tag="a" :href="api.areaTerrainCsvUrl(detail.id)" download>导出CSV</n-button></div><n-data-table v-if="terrainProfiles.length" :columns="terrainColumns" :data="terrainProfiles" :pagination="false"/><n-empty v-else description="暂无地形分析结果"/><p class="muted">相对低高程仅用于辅助解释积水空间分布，不表示该区域必然积水。</p><h4>边界摘要</h4><pre>{{JSON.stringify(detail.geometry_geojson,null,2)}}</pre><h4>基于最近位置快照的关联设备</h4><n-data-table v-if="detail.current_equipment?.length" :columns="equipmentColumns" :data="detail.current_equipment" :pagination="false"/><n-empty v-else description="暂无最近位置落入该区域的工程机械"/><p class="muted">此处“关联设备”仅表示设备最近位置快照落入该区域，不代表设备仍在现场或正在移动。</p><h4>历史水害影响</h4><n-data-table v-if="detail.impact_history?.length" :columns="impactColumns" :data="detail.impact_history" :pagination="false"/><n-empty v-else description="暂无与该区域关联的水害研判结果。"/></template>
  </n-modal>
  <n-card v-if="detail?.assistance_records" class="linked-assistance" title="当前区域作业辅助记录"><n-data-table v-if="detail.assistance_records.length" :columns="[{title:'事项名称',key:'title'},{title:'类型',key:'assistance_type_label'},{title:'优先级',key:'priority_label'},{title:'状态',key:'status_label'},{title:'生成时间',render:(r:any)=>fmt(r.created_at)}]" :data="detail.assistance_records" :pagination="false"/><n-empty v-else description="暂无与该区域关联的作业辅助事项"/><p v-if="detail.latest_assistance_verification" class="muted">最近核查：{{fmt(detail.latest_assistance_verification.verified_at)}} · {{detail.latest_assistance_verification.verification_result_label}}</p></n-card>
</template>

<script setup lang="ts">
import { computed,h,onMounted,ref,watch } from 'vue'
import { NButton,NPopconfirm,NTag,useMessage } from 'naive-ui'
import { api } from '../api'
import type { ConstructionEquipment,ConstructionProject,MultisourceTimelineEvent,RainfallOverview,TerrainDataset,TerrainProfile,UavCoverage,UavDataset,UavProjectSummary,UavVerification,WorkArea,WorkAreaImpact } from '../types'
import { formatDateTime } from '../utils/format'
import { currentProjectId } from '../composables/projectContext'
const msg=useMessage(),projects=ref<ConstructionProject[]>([]),areas=ref<WorkArea[]>([]),dems=ref<TerrainDataset[]>([]),uavs=ref<UavDataset[]>([]),uavCoverages=ref<UavCoverage[]>([]),areaVerifications=ref<UavVerification[]>([]),uavSummary=ref<UavProjectSummary|null>(null),timeline=ref<MultisourceTimelineEvent[]>([]),uavAreaDatasetId=ref<string|null>(null),uavRunning=ref(false),terrainProfiles=ref<TerrainProfile[]>([]),rainOverview=ref<RainfallOverview|null>(null),terrainDemId=ref<string|null>(null),terrainRunning=ref(false),selectedProject=ref<ConstructionProject|null>(null),loading=ref(false),saving=ref(false),showProjectForm=ref(false),showAreaForm=ref(false),detailVisible=ref(false),detail=ref<WorkArea|null>(null)
const projectTypes=[{label:'露天矿山',value:'open_pit_mine'},{label:'土方施工',value:'earthwork'},{label:'大型基础设施',value:'infrastructure'},{label:'道路施工',value:'road_construction'},{label:'其他',value:'other'}]
const areaTypes=[{label:'采坑',value:'pit'},{label:'施工道路区域',value:'construction_road'},{label:'低洼区域',value:'low_lying_area'},{label:'作业面',value:'work_face'},{label:'材料/堆场区域',value:'material_area'},{label:'排水关注区域',value:'drainage_area'},{label:'其他区域',value:'other'}]
const projectForm=ref({id:'',project_name:'',project_code:'',project_type:'open_pit_mine',description:'',location_text:''}),areaForm=ref({id:'',area_name:'',area_code:'',area_type:'pit',description:'',crs:'EPSG:4326',geometryText:''})
const fmt=(v:string)=>formatDateTime(v),pct=(v:number|null|undefined)=>v==null?'--':`${(v*100).toFixed(2)}%`
const rain=(v:number|null)=>v==null?'无数据':`${v.toFixed(2)} mm`
const geoSummary=computed(()=>{try{const g=JSON.parse(areaForm.value.geometryText||'{}');const x=g.type==='Feature'?g.geometry:g;return x?.type?`已读取 ${x.type} 边界；保存时将校验坐标、闭合性和空间参考。`:''}catch{return areaForm.value.geometryText?'GeoJSON 尚未形成合法 JSON。':''}})
const terrainOptions=computed(()=>dems.value.filter(x=>!x.project_id||x.project_id===detail.value?.project_id).map(x=>({label:`${x.name} · ${x.crs}`,value:x.id})))
const uavOptions=computed(()=>uavs.value.filter(x=>x.project_id===detail.value?.project_id).map(x=>({label:`${x.name} · ${x.capture_time?fmt(x.capture_time):'采集时间未填写'}`,value:x.id})))
async function load(){loading.value=true;try{projects.value=await api.projects();if(selectedProject.value){selectedProject.value=projects.value.find(x=>x.id===selectedProject.value?.id)||null;if(selectedProject.value)areas.value=await api.workAreas(selectedProject.value.id)}}catch(e:any){msg.error(e.message)}finally{loading.value=false}}
async function selectProject(p:ConstructionProject){selectedProject.value=p;showProjectForm.value=false;showAreaForm.value=false;loading.value=true;try{[areas.value,rainOverview.value,uavs.value,uavSummary.value,timeline.value]=await Promise.all([api.workAreas(p.id),api.rainfallOverview(p.id),api.uavDatasets(p.id),api.uavProjectSummary(p.id),api.multisourceTimeline(p.id)])}catch(e:any){msg.error(e.message)}finally{loading.value=false}}
function newProject(){projectForm.value={id:'',project_name:'',project_code:'',project_type:'open_pit_mine',description:'',location_text:''};showProjectForm.value=true}
function editProject(){if(!selectedProject.value)return;projectForm.value={id:selectedProject.value.id,project_name:selectedProject.value.project_name,project_code:selectedProject.value.project_code,project_type:selectedProject.value.project_type,description:selectedProject.value.description,location_text:selectedProject.value.location_text};showProjectForm.value=true}
async function saveProject(){const f=projectForm.value;if(!f.project_name.trim()||!f.project_code.trim()){msg.warning('请填写项目名称和编号');return}saving.value=true;try{const payload={project_name:f.project_name.trim(),project_code:f.project_code.trim(),project_type:f.project_type,description:f.description.trim(),location_text:f.location_text.trim()};const saved=f.id?await api.updateProject(f.id,payload):await api.createProject(payload);showProjectForm.value=false;await load();await selectProject(projects.value.find(x=>x.id===saved.id)||saved);msg.success('项目已保存')}catch(e:any){msg.error(e.message)}finally{saving.value=false}}
async function archiveProject(){if(!selectedProject.value)return;try{await api.archiveProject(selectedProject.value.id);await load();msg.success('项目已归档')}catch(e:any){msg.error(e.message)}}
function newArea(){areaForm.value={id:'',area_name:'',area_code:'',area_type:'pit',description:'',crs:'EPSG:4326',geometryText:''};showAreaForm.value=true}
function editArea(row:WorkArea){areaForm.value={id:row.id,area_name:row.area_name,area_code:row.area_code,area_type:row.area_type,description:row.description,crs:row.crs,geometryText:JSON.stringify(row.geometry_geojson,null,2)};showAreaForm.value=true}
async function readGeoJSON(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;try{areaForm.value.geometryText=await file.text();msg.success('GeoJSON 已读取')}catch{msg.error('无法读取文件')}}
async function saveArea(){if(!selectedProject.value)return;let geometry;try{geometry=JSON.parse(areaForm.value.geometryText)}catch{msg.error('GeoJSON JSON格式无效');return}const f=areaForm.value;if(!f.area_name.trim()||!f.area_code.trim()||!f.crs.trim()){msg.warning('请填写区域名称、编号和空间参考');return}saving.value=true;try{const payload={area_name:f.area_name.trim(),area_code:f.area_code.trim(),area_type:f.area_type,description:f.description.trim(),crs:f.crs.trim(),geometry_geojson:geometry,...(!f.id?{project_id:selectedProject.value.id}:{})};f.id?await api.updateWorkArea(f.id,payload):await api.createWorkArea(payload);showAreaForm.value=false;areas.value=await api.workAreas(selectedProject.value.id);await load();msg.success('施工区域已保存')}catch(e:any){msg.error(e.message)}finally{saving.value=false}}
async function openDetail(row:WorkArea){try{[detail.value,terrainProfiles.value,uavCoverages.value,areaVerifications.value]=await Promise.all([api.workArea(row.id),api.areaTerrain(row.id),api.areaUavCoverages(row.id),api.uavVerifications(`work_area_id=${encodeURIComponent(row.id)}`)]);terrainDemId.value=terrainProfiles.value[0]?.dem_id||null;uavAreaDatasetId.value=uavCoverages.value[0]?.uav_dataset_id||null;detailVisible.value=true}catch(e:any){msg.error(e.message)}}
async function runUavCoverage(){if(!detail.value||!uavAreaDatasetId.value)return;uavRunning.value=true;try{await api.runUavAreaCoverage(uavAreaDatasetId.value,detail.value.id);uavCoverages.value=await api.areaUavCoverages(detail.value.id);msg.success('施工区域无人机覆盖分析已完成')}catch(e:any){msg.error(e.message)}finally{uavRunning.value=false}}
async function runTerrain(){if(!detail.value||!terrainDemId.value)return;terrainRunning.value=true;try{await api.runAreaTerrain(detail.value.id,terrainDemId.value);terrainProfiles.value=await api.areaTerrain(detail.value.id);msg.success('区域地形分析已完成')}catch(e:any){msg.error(e.message)}finally{terrainRunning.value=false}}
async function archiveArea(row:WorkArea){try{await api.updateWorkArea(row.id,{status:'archived'});areas.value=await api.workAreas(selectedProject.value!.id);msg.success('施工区域已归档')}catch(e:any){msg.error(e.message)}}
async function removeArea(row:WorkArea){try{await api.removeWorkArea(row.id);areas.value=await api.workAreas(selectedProject.value!.id);await load();msg.success('施工区域已删除')}catch(e:any){msg.error(e.message)}}
const areaColumns=[{title:'区域名称',key:'area_name',width:170},{title:'类型',key:'area_type_label',width:130},{title:'状态',render:(r:WorkArea)=>h(NTag,{type:r.status==='active'?'success':'default'},{default:()=>r.status==='active'?'启用':'已归档'}),width:90},{title:'空间参考',key:'crs',width:130},{title:'Geometry',key:'geometry_type',width:110},{title:'最近影响',render:(r:WorkArea)=>r.latest_impact?h(NTag,{type:r.latest_impact.impact_level.startsWith('高')?'error':r.latest_impact.impact_level.startsWith('中')?'warning':'success'},{default:()=>r.latest_impact!.impact_level}):'暂无',width:120},{title:'高关注占比',render:(r:WorkArea)=>pct(r.latest_impact?.high_attention_ratio),width:110},{title:'更新时间',render:(r:WorkArea)=>fmt(r.updated_at),width:155},{title:'操作',fixed:'right' as const,width:220,render:(r:WorkArea)=>h('div',{style:'display:flex;gap:6px'},[h(NButton,{size:'small',onClick:()=>openDetail(r)},{default:()=>'详情'}),h(NButton,{size:'small',onClick:()=>editArea(r)},{default:()=>'编辑'}),r.status==='active'&&h(NButton,{size:'small',onClick:()=>archiveArea(r)},{default:()=>'归档'}),h(NPopconfirm,{onPositiveClick:()=>removeArea(r)},{trigger:()=>h(NButton,{size:'small',type:'error',secondary:true},{default:()=>'删除'}),default:()=>'仅无历史影响记录的区域可以删除。'})])}]
const impactColumns=[{title:'研判时间',render:(r:WorkAreaImpact)=>fmt(r.created_at)},{title:'高关注',render:(r:WorkAreaImpact)=>pct(r.high_attention_ratio)},{title:'重点巡检',render:(r:WorkAreaImpact)=>pct(r.inspection_ratio)},{title:'一般区域',render:(r:WorkAreaImpact)=>pct(r.general_ratio)},{title:'影响等级',key:'impact_level'}]
const equipmentColumns=[{title:'设备编号',key:'equipment_code'},{title:'设备名称',key:'equipment_name'},{title:'类型',key:'equipment_type_label'},{title:'位置时间',render:(r:ConstructionEquipment)=>fmt(r.latest_position?.recorded_at||'')},{title:'点位水害类别',render:(r:ConstructionEquipment)=>r.latest_risk_link?.risk_label||'暂无关联'}]
const terrainColumns=[{title:'DEM',key:'dem_name'},{title:'最低高程',render:(r:TerrainProfile)=>r.min_elevation==null?'--':`${r.min_elevation.toFixed(2)} m`},{title:'最高高程',render:(r:TerrainProfile)=>r.max_elevation==null?'--':`${r.max_elevation.toFixed(2)} m`},{title:'平均高程',render:(r:TerrainProfile)=>r.mean_elevation==null?'--':`${r.mean_elevation.toFixed(2)} m`},{title:'平均坡度',render:(r:TerrainProfile)=>r.mean_slope==null?'--':`${r.mean_slope.toFixed(2)}°`},{title:'低高程比例',render:(r:TerrainProfile)=>pct(r.low_elevation_ratio)},{title:'分析时间',render:(r:TerrainProfile)=>fmt(r.created_at)}]
const uavCoverageColumns=[{title:'无人机影像',key:'uav_name'},{title:'覆盖状态',key:'coverage_label'},{title:'覆盖比例',render:(r:UavCoverage)=>pct(r.coverage_ratio)},{title:'有效覆盖像素',key:'covered_pixels'},{title:'版本',key:'analysis_version'}]
